namespace composix::core {
namespace hyphen_data {
// One entry a language (generated by CMake from third_party/hyphen, s190).
struct Set { const char* code; const char* patterns; const char* exceptions; };
extern const Set kSets[];
extern const int kSetCount;
}  // namespace hyphen_data

namespace {
// ── UTF-8 ────────────────────────────────────────────────────────────────────
// The code point at s[i] and its length in bytes (0: not valid UTF-8).
char32_t decode(std::string_view s, std::size_t i, int& len) {
    const auto b = [&](std::size_t k) { return k < s.size() ? static_cast<unsigned char>(s[k]) : 0u; };
    const unsigned c = b(i);
    if (c < 0x80) { len = 1; return c; }
    if ((c >> 5) == 0x6 && (b(i + 1) >> 6) == 0x2) { len = 2; return ((c & 0x1F) << 6) | (b(i + 1) & 0x3F); }
    if ((c >> 4) == 0xE && (b(i + 1) >> 6) == 0x2 && (b(i + 2) >> 6) == 0x2) {
        len = 3;
        return ((c & 0x0F) << 12) | ((b(i + 1) & 0x3F) << 6) | (b(i + 2) & 0x3F);
    }
    if ((c >> 3) == 0x1E && (b(i + 1) >> 6) == 0x2 && (b(i + 2) >> 6) == 0x2 && (b(i + 3) >> 6) == 0x2) {
        len = 4;
        return ((c & 0x07) << 18) | ((b(i + 1) & 0x3F) << 12) | ((b(i + 2) & 0x3F) << 6) | (b(i + 3) & 0x3F);
    }
    len = 0;
    return 0;
}
void encode(char32_t c, std::string& out) {
    if (c < 0x80) out += static_cast<char>(c);
    else if (c < 0x800) { out += static_cast<char>(0xC0 | (c >> 6)); out += static_cast<char>(0x80 | (c & 0x3F)); }
    else if (c < 0x10000) {
        out += static_cast<char>(0xE0 | (c >> 12));
        out += static_cast<char>(0x80 | ((c >> 6) & 0x3F));
        out += static_cast<char>(0x80 | (c & 0x3F));
    } else {
        out += static_cast<char>(0xF0 | (c >> 18));
        out += static_cast<char>(0x80 | ((c >> 12) & 0x3F));
        out += static_cast<char>(0x80 | ((c >> 6) & 0x3F));
        out += static_cast<char>(0x80 | (c & 0x3F));
    }
}
// A letter the patterns may know: ASCII, Latin-1 and Latin Extended-A / B.
bool is_letter(char32_t c) {
    if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')) return true;
    if (c >= 0xC0 && c <= 0x24F) return c != 0xD7 && c != 0xF7;   // not x or the division sign
    return false;
}
bool is_apostrophe(char32_t c) { return c == '\'' || c == 0x2019; }
// Lower case, for the scripts above.
char32_t lower(char32_t c) {
    if (c >= 'A' && c <= 'Z') return c + 32;
    if ((c >= 0xC0 && c <= 0xDE) && c != 0xD7) return c + 32;
    if (c >= 0x100 && c <= 0x17F) {   // Latin Extended-A: mostly upper / lower pairs
        if ((c >= 0x139 && c <= 0x148) || (c >= 0x179 && c <= 0x17E)) return (c % 2) ? c + 1 : c;   // odd = upper here
        if (c == 0x130) return 'i';
        if (c == 0x178) return 0xFF;
        return (c % 2) ? c : c + 1;   // even = upper
    }
    return c;
}

// ── the tables ──────────────────────────────────────────────────────────────
struct Tables {
    // letters ("ach", lower case, UTF-8) -> the digits between / around them (size letters + 1)
    std::unordered_map<std::string, std::vector<std::uint8_t>> patterns;
    std::unordered_map<std::string, std::vector<int>>          exceptions;   // "table" -> {2} (letter counts)
    std::size_t longest = 0;   // in letters
};
Tables build(const char* pat, const char* exc) {
    Tables t;
    std::istringstream in(pat ? pat : "");
    std::string tok;
    while (in >> tok) {
        std::string letters;
        std::vector<std::uint8_t> digits(1, 0);
        std::size_t count = 0;
        for (std::size_t i = 0; i < tok.size();) {
            const char ch = tok[i];
            if (ch >= '0' && ch <= '9') { digits.back() = static_cast<std::uint8_t>(ch - '0'); ++i; continue; }
            int len = 0;
            const char32_t c = decode(tok, i, len);
            if (len == 0) { ++i; continue; }
            encode(lower(c), letters);
            digits.push_back(0);
            ++count;
            i += static_cast<std::size_t>(len);
        }
        t.longest = std::max(t.longest, count);
        t.patterns.emplace(std::move(letters), std::move(digits));
    }
    std::istringstream ex(exc ? exc : "");
    while (ex >> tok) {
        std::string word;
        std::vector<int> at;
        int count = 0;
        for (std::size_t i = 0; i < tok.size();) {
            if (tok[i] == '-') { at.push_back(count); ++i; continue; }
            int len = 0;
            const char32_t c = decode(tok, i, len);
            if (len == 0) { ++i; continue; }
            encode(lower(c), word);
            ++count;
            i += static_cast<std::size_t>(len);
        }
        t.exceptions.emplace(std::move(word), std::move(at));
    }
    return t;
}
const Tables& tables(const std::string& code) {
    static std::mutex mx;   // the flow runs on workers too
    static std::map<std::string, Tables> built;
    std::lock_guard lk(mx);
    if (const auto it = built.find(code); it != built.end()) return it->second;
    for (int i = 0; i < hyphen_data::kSetCount; ++i)
        if (code == hyphen_data::kSets[i].code)
            return built.emplace(code, build(hyphen_data::kSets[i].patterns, hyphen_data::kSets[i].exceptions)).first->second;
    return built.emplace(code, Tables{}).first->second;
}
}  // namespace

const std::vector<HyphenLanguage>& hyphen_languages() {
    static const std::vector<HyphenLanguage> v{
        {"en-US", "English (US)", 2, 3}, {"en-GB", "English (UK)", 2, 3}, {"de", "German", 2, 2},
        {"fr", "French", 2, 2},          {"es", "Spanish", 2, 2},         {"it", "Italian", 2, 2},
        {"nl", "Dutch", 2, 2},           {"pt", "Portuguese", 2, 3},
    };
    return v;
}

const HyphenLanguage& hyphen_language(std::string_view code) {
    for (const auto& l : hyphen_languages()) if (code == l.code) return l;
    return hyphen_languages().front();
}

std::vector<int> hyphen_points(std::string_view word, int left, int right, std::string_view lang) {
    const auto& L = hyphen_language(lang);
    if (left < 0) left = L.left;
    if (right < 0) right = L.right;
    // The word's letters (lower case) and where each starts in its bytes.
    std::vector<std::string> letters;
    std::vector<int> starts;
    const bool french = std::string_view(L.code) == "fr";
    for (std::size_t i = 0; i < word.size();) {
        int len = 0;
        const char32_t c = decode(word, i, len);
        if (len == 0) return {};
        if (!is_letter(c) && !(french && is_apostrophe(c) && !letters.empty())) return {};
        std::string u;
        encode(is_apostrophe(c) ? char32_t{'\''} : lower(c), u);
        letters.push_back(std::move(u));
        starts.push_back(static_cast<int>(i));
        i += static_cast<std::size_t>(len);
    }
    const int n = static_cast<int>(letters.size());
    if (n < left + right) return {};
    const auto& t = tables(L.code);
    std::vector<int> out;
    std::string w;
    for (const auto& l : letters) w += l;
    if (const auto it = t.exceptions.find(w); it != t.exceptions.end()) {
        for (int k : it->second) if (k >= left && n - k >= right) out.push_back(starts[static_cast<std::size_t>(k)]);
        return out;
    }
    std::vector<std::string> dotted{"."};
    dotted.insert(dotted.end(), letters.begin(), letters.end());
    dotted.push_back(".");
    const int m = static_cast<int>(dotted.size());
    std::vector<std::uint8_t> v(static_cast<std::size_t>(m) + 1, 0);
    for (int i = 0; i < m; ++i) {
        std::string key;
        for (int len = 1; len <= static_cast<int>(t.longest) && i + len <= m; ++len) {
            key += dotted[static_cast<std::size_t>(i + len - 1)];
            const auto it = t.patterns.find(key);
            if (it == t.patterns.end()) continue;
            for (int k = 0; k <= len; ++k)
                v[static_cast<std::size_t>(i + k)] = std::max(v[static_cast<std::size_t>(i + k)], it->second[static_cast<std::size_t>(k)]);
        }
    }
    // v[k + 1]: between letter k - 1 and letter k (the leading dot shifts by one).
    for (int k = left; k <= n - right; ++k)
        if (v[static_cast<std::size_t>(k + 1)] % 2) out.push_back(starts[static_cast<std::size_t>(k)]);
    return out;
}

std::string hyphenated(std::string_view word, std::string_view lang) {
    std::string out;
    const auto at = hyphen_points(word, -1, -1, lang);
    std::size_t j = 0;
    for (std::size_t k = 0; k < word.size(); ++k) {
        if (j < at.size() && at[j] == static_cast<int>(k)) { out += '-'; ++j; }
        out += word[k];
    }
    return out;
}

}  // namespace composix::core
